patch.content:
&i2c0 { /* Assuming I2C bus 0 is available and enabled */
	ltc2959_0: ltc2959@68 {
		compatible = "adi,ltc2959";
		reg = <0x68>; /* Example I2C address, adjust if different */
		rsense-milliohms = <10>; /* Example value, adjust to your shunt resistor value */
		status = "okay";
	};
};
